"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[6579],{3331:(i,e,a)=>{a.d(e,{R:()=>r,x:()=>l});var o=a(36672);const n={},t=o.createContext(n);function r(i){const e=o.useContext(t);return o.useMemo((function(){return"function"==typeof i?i(e):{...e,...i}}),[e,i])}function l(i){let e;return e=i.disableParentContext?"function"==typeof i.components?i.components(n):i.components||n:r(i.components),o.createElement(t.Provider,{value:e},i.children)}},18232:(i,e,a)=>{a.r(e),a.d(e,{assets:()=>s,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"2023/04/08","title":"2023-04-08","description":"Costruire GitHub con Ruby on Rails","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/08.md","sourceDirName":"2023/04","slug":"/2023/04/08","permalink":"/it/2023/04/08","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/08.md","tags":[],"version":"current","frontMatter":{"localized_date":"8 aprile 2023","top_news":"Costruire GitHub con Ruby on Rails"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-09","permalink":"/it/2023/04/09"},"next":{"title":"2023-04-07","permalink":"/it/2023/04/07"}}');var n=a(23420),t=a(3331);const r={localized_date:"8 aprile 2023",top_news:"Costruire GitHub con Ruby on Rails"},l="2023-04-08",s={},c=[{value:"Costruire GitHub con Ruby on Rails",id:"costruire-github-con-ruby-on-rails",level:2},{value:"Ask Wirecutter: Puoi consigliarmi un televisore non intelligente?",id:"ask-wirecutter-puoi-consigliarmi-un-televisore-non-intelligente",level:2},{value:"Codeberg - Alternativa open source veloce a GitHub",id:"codeberg---alternativa-open-source-veloce-a-github",level:2},{value:"Riso perenne: Piantare una volta, raccogliere ancora e ancora",id:"riso-perenne-piantare-una-volta-raccogliere-ancora-e-ancora",level:2},{value:"60 milioni di americani hanno tasse cos\xec semplici che il fisco potrebbe farle automaticamente.",id:"60-milioni-di-americani-hanno-tasse-cos\xec-semplici-che-il-fisco-potrebbe-farle-automaticamente",level:2},{value:"Dobbiamo dire alle persone che ChatGPT mentir\xe0 loro, non discutere di linguistica.",id:"dobbiamo-dire-alle-persone-che-chatgpt-mentir\xe0-loro-non-discutere-di-linguistica",level:2},{value:"Twitter non permette il retweet di tweet che collegano a Substack",id:"twitter-non-permette-il-retweet-di-tweet-che-collegano-a-substack",level:2},{value:"I servizi cloud di Western Digital non funzionano per 4 giorni.",id:"i-servizi-cloud-di-western-digital-non-funzionano-per-4-giorni",level:2},{value:"Come funziona lo sharding dei database?",id:"come-funziona-lo-sharding-dei-database",level:2},{value:"Hubble vede un possibile buco nero in fuga che crea una scia di stelle",id:"hubble-vede-un-possibile-buco-nero-in-fuga-che-crea-una-scia-di-stelle",level:2},{value:"La pi\xf9 grande violazione di dati in NZ dimostra che la retention \xe8 il gigante addormentato della sicurezza dei dati",id:"la-pi\xf9-grande-violazione-di-dati-in-nz-dimostra-che-la-retention-\xe8-il-gigante-addormentato-della-sicurezza-dei-dati",level:2},{value:"Stati Uniti e Cina si fanno la guerra sotto le onde per i cavi internet",id:"stati-uniti-e-cina-si-fanno-la-guerra-sotto-le-onde-per-i-cavi-internet",level:2},{value:"Lo &quot;sharding&quot; dei database proviene da Ultima Online?",id:"lo-sharding-dei-database-proviene-da-ultima-online",level:2},{value:"Perch\xe9 Phreesia ha condiviso i miei dati medici dopo che ho scelto di non farlo?",id:"perch\xe9-phreesia-ha-condiviso-i-miei-dati-medici-dopo-che-ho-scelto-di-non-farlo",level:2},{value:"JavaScript-algoritmi: Algoritmi e strutture dati implementati in JavaScript",id:"javascript-algoritmi-algoritmi-e-strutture-dati-implementati-in-javascript",level:2},{value:"SpaceX si avvicina al primo lancio della Starship Super Heavy",id:"spacex-si-avvicina-al-primo-lancio-della-starship-super-heavy",level:2},{value:"Costruire sintetizzatori musicali con query SQL",id:"costruire-sintetizzatori-musicali-con-query-sql",level:2},{value:"La pi\xf9 lunga linea retta in Gran Bretagna senza attraversare una strada pubblica",id:"la-pi\xf9-lunga-linea-retta-in-gran-bretagna-senza-attraversare-una-strada-pubblica",level:2},{value:"Flipper Zero bandito da Amazon per essere un &quot;dispositivo di scrematura delle carte di credito&quot;.",id:"flipper-zero-bandito-da-amazon-per-essere-un-dispositivo-di-scrematura-delle-carte-di-credito",level:2},{value:"Reverse Engineering dell&#39;API di Facebook Messenger",id:"reverse-engineering-dellapi-di-facebook-messenger",level:2},{value:"Le macchine di Tatjana van Vark",id:"le-macchine-di-tatjana-van-vark",level:2},{value:"Grande palla di fango (1999)",id:"grande-palla-di-fango-1999",level:2},{value:"Yann LeCun e Andrew Ng: Perch\xe9 la pausa di 6 mesi sull&#39;intelligenza artificiale \xe8 una cattiva idea [video].",id:"yann-lecun-e-andrew-ng-perch\xe9-la-pausa-di-6-mesi-sullintelligenza-artificiale-\xe8-una-cattiva-idea-video",level:2},{value:"L&#39;NSA ha creato un corso online di cybersicurezza con 100 classi",id:"lnsa-ha-creato-un-corso-online-di-cybersicurezza-con-100-classi",level:2},{value:"Sostituzione di cattivi sistemi con cattivi sistemi",id:"sostituzione-di-cattivi-sistemi-con-cattivi-sistemi",level:2},{value:"Neovim 0.9",id:"neovim-09",level:2},{value:"Qual \xe8 la vostra migliore risorsa per tenervi aggiornati sugli sviluppi dell&#39;intelligenza artificiale?",id:"qual-\xe8-la-vostra-migliore-risorsa-per-tenervi-aggiornati-sugli-sviluppi-dellintelligenza-artificiale",level:2},{value:"Prova diretta dell&#39;uso di pi\xf9 droghe nell&#39;Et\xe0 del Bronzo dal test sui capelli umani",id:"prova-diretta-delluso-di-pi\xf9-droghe-nellet\xe0-del-bronzo-dal-test-sui-capelli-umani",level:2},{value:"Agenti della polizia di New York si vantano di fare gli straordinari in una registrazione accidentale",id:"agenti-della-polizia-di-new-york-si-vantano-di-fare-gli-straordinari-in-una-registrazione-accidentale",level:2},{value:"Mostra ChatGDB - Assistente GDB alimentato da GPT",id:"mostra-chatgdb---assistente-gdb-alimentato-da-gpt",level:2}];function d(i){const e={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...i.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(e.header,{children:(0,n.jsx)(e.h1,{id:"2023-04-08",children:"2023-04-08"})}),"\n",(0,n.jsx)(e.h2,{id:"costruire-github-con-ruby-on-rails",children:"Costruire GitHub con Ruby on Rails"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.blog/2023-04-06-building-github-with-ruby-and-rails/",children:"Originale"}),".\nGitHub.com \xe8 scritto con Ruby on Rails e gestito da oltre mille ingegneri con quasi 2 milioni di linee di codice. L'azienda aggiorna settimanalmente l'ultimo commit di Rails con richieste di pull e revisioni. I vantaggi di questi aggiornamenti includono una migliore gestione delle connessioni al database e un rendering pi\xf9 rapido delle visualizzazioni, una maggiore sicurezza e un minor rischio di problemi sconosciuti. I test delle ultime versioni identificano e risolvono i problemi prima del rilascio. Il post \xe8 una dichiarazione sulla privacy di GitHub, contenente informazioni sulle caratteristiche del prodotto, sulla sicurezza, sulle storie, sui prezzi, sulle risorse, sulle API per gli sviluppatori, sui partner, sulla piattaforma e sul supporto. Il post non sembra contenere nuove informazioni o eventi e non \xe8 chiaro il motivo dell'attenzione."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35478884",children:"Discussion Service"}),".\nGitHub ha ricostruito la sua piattaforma con Ruby on Rails, suscitando interesse per il suo potenziale impatto sull'ecosistema Rails e sui requisiti di copertura dei test. Gli utenti sottolineano le sfide legate alla padronanza di Ruby, come l'estrema copertura dei test e il potenziale di futuri fallimenti del codice. Alcuni utenti suggeriscono di usare Sorbet per i tipi di controllo pi\xf9 forti. L'uso di GitHub del linguaggio Crystal e il potenziale di metaprogrammazione di Ruby vengono elogiati, mentre alcuni criticano lo spazio di Ruby per la scienza dei dati. Il recente aggiornamento della piattaforma Rails di Github dalla versione 2.3 alla 3 ha posto delle sfide, ma la tipizzazione statica aiuta gli aggiornamenti. Gli sviluppatori riflettono sui compromessi tra tendenze tecnologiche e stabilit\xe0 consolidata, con alcuni che sottolineano la facilit\xe0 d'uso di Rails ma il ritardo del livello di visualizzazione. Gli aggiornamenti del framework sono pi\xf9 efficaci se fatti gradualmente, con un buon test in atto. Molte organizzazioni considerano importante l'aggiornamento dell'infrastruttura IT, le capacit\xe0 di testing di GitHub vengono elogiate e Sorbet viene utilizzato da GitHub per Ruby e Rails."]}),"\n",(0,n.jsx)(e.h2,{id:"ask-wirecutter-puoi-consigliarmi-un-televisore-non-intelligente",children:"Ask Wirecutter: Puoi consigliarmi un televisore non intelligente?"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.nytimes.com/wirecutter/blog/ask-wirecutter-dumb-tvs/",children:"Originale"}),".\nWirecutter suggerisce di proteggere i televisori intelligenti invece di trovare opzioni non intelligenti a causa di problemi di privacy. I televisori disconnessi potrebbero essere privi di funzioni utili. Gli esperti consigliano di rinunciare alla raccolta dei dati, di connettersi al Wi-Fi solo per gli aggiornamenti del firmware e di interrompere occasionalmente lo streaming. Le alternative sono vecchi televisori, monitor 4K o proiettori. Problemi di privacy simili persistono con altri dispositivi connessi a Internet."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35484594",children:"Discussion Service"}),".\nIn un articolo si parla della difficolt\xe0 di trovare un televisore non intelligente senza funzioni invasive e non necessarie. Le soluzioni suggerite includono l'uso di una smart TV scollegata o la disconnessione fisica dei moduli per evitare connessioni indesiderate. Ci sono preoccupazioni sulla privacy e sull'infiltrazione dei dati. Discussione sul consumo di energia, sulle potenziali connessioni automatiche e sulla lentezza del processo di avvio delle smart TV da parte degli utenti. Suggerimenti su un potenziale nome per una smart TV non intelligente e sulle caratteristiche ideali di una smart TV. Preoccupazione per il tracciamento dei dati e per la difficolt\xe0 di avviare un'impresa con display muti e di alta qualit\xe0. Gli utenti discutono delle caratteristiche specifiche dei display e della difficolt\xe0 di mantenere le smart TV non connesse. Vengono evidenziati il comportamento non etico di TCL e i problemi di privacy degli utenti."]}),"\n",(0,n.jsx)(e.h2,{id:"codeberg---alternativa-open-source-veloce-a-github",children:"Codeberg - Alternativa open source veloce a GitHub"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://codeberg.org/",children:"Originale"}),".\nCodeberg.org \xe8 una piattaforma di collaborazione software libera e open-source e un hosting Git gestito dai suoi utenti tramite un'organizzazione no-profit di Berlino. La piattaforma promuove anche una comunit\xe0 di creatori di software libero e di contenuti che la pensano allo stesso modo, senza tracciamento o vendita dei dati degli utenti. Gli utenti possono registrarsi e ospitare i loro progetti sul sito web, e Codeberg e.V. sostiene la comunit\xe0 attraverso donazioni e contributi facoltativi. Il sito \xe8 accessibile in pi\xf9 lingue e gli utenti possono offrire contributi per migliorare i servizi di Codeberg."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35480056",children:"Discussion Service"}),".\nCodeberg offre un'alternativa veloce e open-source a Github, incentrata sulla collaborazione tra software libero e open-source. Gli utenti di Discussion Service discutono se l'attenzione di Codeberg all'etica dell'open source sia troppo restrittiva, mentre altri ne lodano l'impegno. Discutendo della natura politica dell'infrastruttura IT, alcuni sostengono che la neutralit\xe0 sia impossibile ma che vada comunque perseguita, mentre altri sostengono che le opinioni politiche siano pi\xf9 tollerabili nell'IT che in altri contesti. Gli utenti di Discussion Service discutono anche della filosofia di condivisione del codice, delle licenze restrittive e dell'impatto dei codici favorevoli alle aziende sui tassi di successo del FOSS. Di Codeberg vengono lodati lo status di no-profit e l'impegno nei confronti delle licenze di software libero. La velocit\xe0 della piattaforma e l'interfaccia semplice sono apprezzate, ma ci sono problemi di privacy. Alcuni raccomandano Radicle come alternativa ai servizi centralizzati come Github."]}),"\n",(0,n.jsx)(e.h2,{id:"riso-perenne-piantare-una-volta-raccogliere-ancora-e-ancora",children:"Riso perenne: Piantare una volta, raccogliere ancora e ancora"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.npr.org/2023/03/23/1165680024/perennial-rice-plant-once-harvest-again-and-again",children:"Originale"}),".\nGli scienziati hanno creato variet\xe0 di riso perenne che rimangono produttive e ricrescono dopo ogni raccolto, con enormi vantaggi per l'ambiente, una minore impronta di carbonio, un suolo pi\xf9 sano e la possibilit\xe0 per gli agricoltori di non dover riseminare. Questi ceppi, allevati negli ultimi due decenni, sono stati testati e raccolti per quattro anni di fila da 45.000 piccoli agricoltori di sussistenza. Gli esperti prevedono che se un numero maggiore di agricoltori adotter\xe0 le nuove variet\xe0, i benefici potrebbero essere notevoli per le persone che le coltivano, per l'ambiente e per la popolazione mondiale che si affida al riso come alimento di base."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35481409",children:"Discussion Service"}),".\nIl riso perenne pu\xf2 ridurre le emissioni di metano dalle risaie. La produzione di bestiame ha un impatto ambientale significativo. Il cambiamento climatico porter\xe0 a carenze alimentari e ad altri problemi. Il metano prodotto dalle risaie non ha un impatto significativo rispetto ad altre fonti. Il riso perenne presenta potenziali benefici ma anche sfide. Gli esperti discutono di agricoltura e produzione alimentare. Viene illustrato il successo del riso perenne irrigato. Le colture perenni possono far risparmiare sui costi della manodopera e degli input. Le piante perenni hanno benefici per il suolo e per l'estrazione dei nutrienti."]}),"\n",(0,n.jsx)(e.h2,{id:"60-milioni-di-americani-hanno-tasse-cos\xec-semplici-che-il-fisco-potrebbe-farle-automaticamente",children:"60 milioni di americani hanno tasse cos\xec semplici che il fisco potrebbe farle automaticamente."}),"\n",(0,n.jsxs)(e.p,{children:["(",(0,n.jsx)(e.a,{href:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns",children:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns"}),").\nAlmeno il 41% delle famiglie americane, pari a 62 milioni di unit\xe0 fiscali, potrebbe avere l'intera dichiarazione dei redditi gestita dall'IRS attraverso \"dichiarazioni precompilate\" senza bisogno di ulteriori interventi. Secondo l'approccio meno prudente, il numero \xe8 di 73 milioni di dichiarazioni, pari al 48%. Il potenziale delle dichiarazioni automatiche potrebbe far risparmiare tempo e arrabbiature ogni anno, rendendo pi\xf9 efficiente la stagione fiscale. L'articolo passa poi a trattare brevemente altri argomenti non correlati alle tasse, come la crisi degli abusi sessuali della Chiesa cattolica e le telecamere di Tesla sotto esame. Tuttavia, l'articolo mette in evidenza soprattutto le soluzioni uniche a problemi importanti, trattate nella newsletter di Future Perfect. L'articolo rimane neutrale e informativo, senza alcun pregiudizio politico o religioso."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35476709",children:"Discussion Service"}),".\nLe tasse di 60 milioni di americani sono abbastanza semplici da essere calcolate automaticamente dall'IRS. Il modo pi\xf9 semplice per l'IRS di guadagnare denaro \xe8 l'audit dei soggetti finanziariamente vulnerabili. Intuit contribuisce al fenomeno delle leggi opache. L'applicazione del fisco \xe8 limitata, quindi gli americani a basso reddito sono sottoposti a maggiori controlli. Le recenti modifiche fiscali riducono il margine di manovra per le detrazioni per categoria. L'IRS non \xe8 in grado di massimizzare la sua capacit\xe0 fiscale automatica. Il budget dell'IRS \xe8 diminuito, ma recentemente \xe8 stato aumentato; alcuni ritengono che i fondi supplementari consentiranno all'IRS di massimizzare le entrate invece di rivolgersi a persone specifiche. Proposta di tassare in base all'aliquota X, archiviare se non si \xe8 d'accordo. Le dichiarazioni precompilate farebbero risparmiare tempo e denaro, ma non sono infallibili. Le lobby aziendali contribuiscono alla complessit\xe0 dell'attuale sistema fiscale self-service. Le detrazioni fiscali per le transazioni in contanti mancano di fattibilit\xe0 per l'automazione. La preparazione delle tasse fa perdere miliardi di dollari e di tempo."]}),"\n",(0,n.jsx)(e.h2,{id:"dobbiamo-dire-alle-persone-che-chatgpt-mentir\xe0-loro-non-discutere-di-linguistica",children:"Dobbiamo dire alle persone che ChatGPT mentir\xe0 loro, non discutere di linguistica."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://simonwillison.net/2023/Apr/7/chatgpt-lies/",children:"Originale"}),".\nL'articolo discute i problemi legati ai modelli linguistici di grandi dimensioni (LLM) come ChatGPT, che possono mentire alle persone e presentare bug che non possono essere risolti. L'autore sostiene che \xe8 pi\xf9 importante mettere in guardia le persone sui rischi dell'uso degli LLM piuttosto che discutere di linguistica. Sebbene gli LLM possano essere utili, non sono senzienti e non ci si pu\xf2 fidare che forniscano informazioni concrete. L'articolo solleva questioni etiche sull'opportunit\xe0 o meno di incoraggiare le persone a utilizzare le LLM nonostante i loro difetti. L'autore conclude che \xe8 importante avvicinarsi agli LLM con cautela e sottolinea la necessit\xe0 di avvertire le persone che i ChatGPT possono mentire."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35483823",children:"Discussion Service"}),".\nChatGPT pu\xf2 trarre in inganno gli utenti e bisogna dire ripetutamente di non fidarsi. La sua utilit\xe0 pu\xf2 essere limitata se non si risolve la tendenza alle allucinazioni. ChatGPT non ha capacit\xe0 di ragionamento e pu\xf2 generare informazioni false. Alcuni sono entusiasti dei suoi potenziali progressi, ma altri lo criticano per la sua mancanza di capacit\xe0 di astrazione o di ragionamento. Il testo generato dall'intelligenza artificiale richiede scetticismo e dovrebbe essere visto come un assistente ben preparato ma potenzialmente incline alla confabulazione. Tuttavia, ChatGPT \xe8 utile per generare esempi di codice e rispondere a domande complesse. Offre risposte accurate fino al 99% delle volte. Gli utenti devono comprendere i suoi limiti per evitare di assegnare a ChatGPT pi\xf9 moralit\xe0 del necessario."]}),"\n",(0,n.jsx)(e.h2,{id:"twitter-non-permette-il-retweet-di-tweet-che-collegano-a-substack",children:"Twitter non permette il retweet di tweet che collegano a Substack"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://arstechnica.com/tech-policy/2023/04/the-dumb-reason-twitter-wont-allow-retweeting-tweets-linking-to-substack/",children:"Originale"}),".\nTwitter ha iniziato a limitare i tweet contenenti link a Substack.com in risposta all'annuncio di Substack di un nuovo prodotto, Notes, che far\xe0 concorrenza diretta a Twitter. Gli utenti hanno notato che non possono retwittare o rispondere ai tweet con link a Substack e Twitter ha apparentemente iniziato a bloccare l'inserimento di tweet nei post di Substack. Si ritiene che questa restrizione sia il tentativo di Twitter di limitare la portata di un rivale sulla sua piattaforma. Twitter ha iniziato a bloccare i link a piattaforme di social media concorrenti nel dicembre 2022. Substack non ha ancora risposto alle domande su questo argomento."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35482222",children:"Discussion Service"}),".\nTwitter ha vietato i retweet dei tweet che collegano a Substack, e il gradimento di tali post sopprime la discussione. La mossa ha scatenato critiche sulla libert\xe0 di parola, sulla posizione di Elon Musk al riguardo e sulla concorrenza di Substack. Per alcuni Mastodon sostituisce Twitter. Si discute di PR, dipendenza dai social media e pratiche discutibili. Non viene menzionata alcuna nuova tecnologia o release."]}),"\n",(0,n.jsx)(e.h2,{id:"i-servizi-cloud-di-western-digital-non-funzionano-per-4-giorni",children:"I servizi cloud di Western Digital non funzionano per 4 giorni."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://status.mycloud.com/os4",children:"Originale"}),".\nWestern Digital ha subito un'interruzione iniziata il 2 aprile, con ripercussioni sui servizi My Cloud, My Cloud Home, SanDisk ibi e altri prodotti correlati, con un aggiornamento pubblicato il 3 aprile. L'interruzione \xe8 continuata fino al 7 aprile, con ripercussioni sull'accesso ai file e alle applicazioni. \xc8 disponibile l'accesso locale, che consente agli utenti di accedere ai propri file personali da un computer Windows o MacOS. Altri incidenti passati includono problemi di accesso intermittente, reset intermittente della password e problemi di connettivit\xe0 intermittente con i servizi cloud. Anche alcuni utenti in Cina potrebbero avere problemi di accesso."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35478007",children:"Discussion Service"}),".\nI servizi cloud di Western Digital sono rimasti inattivi per quattro giorni, con commenti che discutono dell'interruzione e della garanzia dell'azienda. Alcuni utenti discutono dei limiti del modello linguistico di GPT e del suo modello mondiale, sollevando dubbi sulla comprensione di concetti complessi. I commenti esplorano anche i termini legali relativi alla responsabilit\xe0 e alle garanzie del servizio di GPT. Gli utenti discutono il valore delle pagine di stato durante le interruzioni, e alcuni suggeriscono metodi alternativi come la chat. Gli utenti discutono i pro e i contro del self-hosting, auspicando un futuro in cui i contenuti multimediali siano accessibili da qualsiasi luogo. I problemi riscontrati in passato da Western Digital con le unit\xe0 SMR non contrassegnate in modo appropriato hanno spinto alcuni utenti a chiedere il ritorno a soluzioni locali."]}),"\n",(0,n.jsx)(e.h2,{id:"come-funziona-lo-sharding-dei-database",children:"Come funziona lo sharding dei database?"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://planetscale.com/blog/how-does-database-sharding-work",children:"Originale"}),".\nL'articolo approfondisce lo sharding dei database, spiegando i vantaggi dello scaling-out anzich\xe9 dello scaling-up con vari schemi e algoritmi di sharding. Copre aspetti vitali come l'organizzazione dell'infrastruttura, la creazione del livello di routing e la pianificazione della migrazione, sottolineando l'importanza della manutenzione. Viene fornita una breve panoramica di framework e strumenti di sharding come Vitess e Citus, mentre CockroachDB inaugura l'era dei database \"senza server\". PlanetScale, un attore emergente del mercato, offre un database shard-nativo costruito su MySQL e Vitess insieme alle sue risorse ingegneristiche."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35476518",children:"Discussion Service"}),".\nDibattiti sui vantaggi e le sfide dello sharding dei database; optare per un sistema che corrisponda ai dati; il throughput dei tasti a caldo \xe8 un problema nell'auto-sharding; alternative Spanner/Cockroach o Dynamo/Cassandra; CockroachDB offre una forte coerenza e 2PC tra gli shard; le complessit\xe0 della distribuzione richiedono servizi a pagamento; concentrarsi sulla scalabilit\xe0 orizzontale per evitare di investire in una singola macchina; una buona progettazione delle chiavi pu\xf2 prevenire gli hotspot; lo sharding per cliente \xe8 comune; lo sharding multi-tenant \xe8 suggerito per la scalabilit\xe0; sono stati citati Yugabyte, Cockroach e TiDB; l'hashing di tutti i dati per la sincronizzazione non \xe8 scalabile; i truffatori sfruttano la pratica di colocazione delle tabelle di Amazon; MongoDB richiede un contratto di supporto aziendale."]}),"\n",(0,n.jsx)(e.h2,{id:"hubble-vede-un-possibile-buco-nero-in-fuga-che-crea-una-scia-di-stelle",children:"Hubble vede un possibile buco nero in fuga che crea una scia di stelle"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://hubblesite.org/contents/news-releases/2023/news-2023-010",children:"Originale"}),".\nImpossibile generare un riepilogo perch\xe9 il testo \xe8 un messaggio di errore che indica che non \xe8 stato possibile soddisfare la richiesta a causa di un errore di configurazione o di un traffico eccessivo. Contattare il proprietario dell'applicazione o del sito web o consultare la documentazione di CloudFront pu\xf2 aiutare a risolvere i problemi e a prevenire il verificarsi di questo errore."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35476359",children:"Discussion Service"}),".\nIl telescopio Hubble ha visto un buco nero che ha lasciato una scia di stelle, portando a speculazioni sul suo effetto sulla vita e su nuovi luoghi dove trovare pianeti abitabili. Hubble ha anche trovato una rara galassia di tipo Hoag, grande circa il doppio della Via Lattea. Gli scienziati hanno scoperto un buco nero che crea stelle dal gas e che potrebbe influenzare l'universo e attirare civilt\xe0 avanzate. Un oggetto che viaggia nello spazio molto velocemente sta creando un impatto supersonico sul gas, ma l'uso di \"supersonico\" \xe8 probabilmente metaforico. Gli utenti di Discussion Service discutono di storie di fantascienza come Il problema dei tre corpi, riflettendo opinioni diverse e consigliando altri libri del genere. Gli utenti discutono anche della rarit\xe0 della vita simile alla Terra e del Principio di Antropomorfia."]}),"\n",(0,n.jsx)(e.h2,{id:"la-pi\xf9-grande-violazione-di-dati-in-nz-dimostra-che-la-retention-\xe8-il-gigante-addormentato-della-sicurezza-dei-dati",children:"La pi\xf9 grande violazione di dati in NZ dimostra che la retention \xe8 il gigante addormentato della sicurezza dei dati"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.privacy.org.nz/publications/statements-media-releases/new-zealands-biggest-data-breach-shows-retention-is-the-sleeping-giant-of-data-security/",children:"Originale"}),".\nOltre un milione di patenti e passaporti neozelandesi sono stati esposti nella violazione dei dati di Latitude Financial; alcuni record risalivano fino a 18 anni fa. Il vice commissario neozelandese per la privacy cita la conservazione dei dati come un problema critico negli attacchi di cybersecurity, affermando che le aziende e le organizzazioni devono limitare la raccolta e la conservazione di dati non necessari. Le agenzie dovrebbero stabilire un programma di conservazione delle informazioni personali e i singoli dovrebbero contestare le organizzazioni a cui forniscono informazioni sul perch\xe9 e sul come vengono conservate. La privacy deve diventare una questione aziendale cruciale, con una protezione simile a quella della salute e della sicurezza. Latitude Financial sta contattando tutti i clienti interessati per informarli della violazione e aiutarli a risolverla, mentre collabora con le autorit\xe0 di regolamentazione per svelare i dettagli della violazione."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35478240",children:"Discussion Service"}),".\nLa pi\xf9 grande violazione di dati della Nuova Zelanda sottolinea la necessit\xe0 di politiche di conservazione dei dati adeguate; l'eliminazione deve essere prioritaria. Il GDPR ha fatto passi da gigante, ma la conservazione dei dati \xe8 ancora molto diffusa. Gli utenti di Discussion Service discutono di raccolta responsabile dei dati, accesso governativo e sicurezza dei dati. Si discute sui metodi di cancellazione dei dati e sulle ragioni della loro conservazione. I dati personali devono essere ridotti al minimo e trattati come beni tossici. Le aziende hanno bisogno di una migliore formazione sulla privacy dei dati."]}),"\n",(0,n.jsx)(e.h2,{id:"stati-uniti-e-cina-si-fanno-la-guerra-sotto-le-onde-per-i-cavi-internet",children:"Stati Uniti e Cina si fanno la guerra sotto le onde per i cavi internet"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.reuters.com/investigates/special-report/us-china-tech-cables/",children:"Originale"}),".\nStati Uniti e Cina sono in lotta per i cavi sottomarini che trasmettono qualsiasi cosa, dalle e-mail ai segreti militari. Negli ultimi quattro anni, il governo statunitense \xe8 intervenuto in almeno sei accordi per la costruzione di cavi sottomarini privati, al fine di isolare il settore high-tech cinese e limitare l'accesso dei cinesi alla tecnologia statunitense. Di recente, la Casa Bianca ha assegnato il contratto per il cavo Singapore-Francia alla SubCom, con sede negli Stati Uniti, anzich\xe9 alla cinese HMN Tech, per motivi di sicurezza. Gli sforzi aggressivi del governo statunitense per impedire lo spionaggio cinese attraverso i cavi sottomarini stanno sconvolgendo i piani dei giganti tecnologici e causando scompiglio nel settore. La Cina si sta vendicando ritardando un progetto di cavo sostenuto da Meta, il cavo Southeast Asia-Giappone 2."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35481712",children:"Discussion Service"}),'.\nGli Stati Uniti e la Cina sono in competizione per i cavi Internet sottomarini, con problemi di confini nazionali e censura. I ritardi e le deviazioni dei cavi sono costati milioni ai giganti della tecnologia. Gli esperti raccomandano libri sulle infrastrutture internazionali. Gli Stati Uniti sono preoccupati per lo spionaggio cinese e per la loro capacit\xe0 di raccogliere e filtrare il traffico internet. Il coinvolgimento della Cina nel Movimento dei non allineati e nella Belt and Road Initiative solleva dubbi. Molte aziende di "cybersecurity" non hanno ingegneri qualificati. Si discute del programma di tortura della CIA e della responsabilit\xe0 per i crimini di guerra.']}),"\n",(0,n.jsx)(e.h2,{id:"lo-sharding-dei-database-proviene-da-ultima-online",children:'Lo "sharding" dei database proviene da Ultima Online?'}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.raphkoster.com/2009/01/08/database-sharding-came-from-uo/",children:"Originale"}),".\nSpiacente, non posso generare un riassunto basato su questo testo poich\xe9 si tratta di un messaggio di errore e non \xe8 correlato all'argomento indicato."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35479553",children:"Discussion Service"}),'.\nGli utenti di Discussion Service discutono di come lo "sharding" nei database sia stato ispirato da Ultima Online. Storie personali raccontano come UO abbia portato all\'apprendimento del codice. I poster ricordano le caratteristiche del gioco di UO e il suo impatto sulla programmazione.']}),"\n",(0,n.jsx)(e.h2,{id:"perch\xe9-phreesia-ha-condiviso-i-miei-dati-medici-dopo-che-ho-scelto-di-non-farlo",children:"Perch\xe9 Phreesia ha condiviso i miei dati medici dopo che ho scelto di non farlo?"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.statnews.com/2023/04/07/medical-data-privacy-phreesia/",children:"Originale"}),".\nUn rapporto evidenzia come le aziende mediche condividano i dati dei pazienti senza consenso. La paziente ha rifiutato la condivisione dei dati, ma i suoi dati sono stati comunque condivisi da Phreesia. Suggerimento di una regola che impedisca di fare pressione sul paziente per ottenere il consenso. Necessit\xe0 di un opt-out predefinito per rendere la rinuncia chiara e semplice. L'attuale processo \xe8 oneroso. L'esperto suggerisce di separare l'ad tech dalla sanit\xe0. L'autore \xe8 un sociologo etnografico e ricercatore di dati."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35484978",children:"Discussion Service"}),".\nPhreesia ha condiviso i dati medici dei pazienti che hanno scelto di non partecipare. Molti esprimono preoccupazioni sulla privacy e sulla responsabilit\xe0 dei dati, suggerendo che la pubblicit\xe0 che utilizza dati medici sensibili non dovrebbe essere legalmente consentita. \xc8 necessario documentare e riferire adeguatamente per ritenere tali societ\xe0 responsabili delle violazioni della privacy. L'uso dei check-in elettronici e dei modelli oscuri da parte dei fornitori di servizi sanitari \xe8 stato criticato. Negli Stati Uniti sono necessarie leggi rigorose sul consenso e sull'applicazione della raccolta dei dati. Sono stati messi in discussione anche i motivi di profitto degli operatori sanitari e il risentimento per le norme sulla privacy dei pazienti."]}),"\n",(0,n.jsx)(e.h2,{id:"javascript-algoritmi-algoritmi-e-strutture-dati-implementati-in-javascript",children:"JavaScript-algoritmi: Algoritmi e strutture dati implementati in JavaScript"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/trekhleb/javascript-algorithms",children:"Originale"}),".\nJavaScript-Algoritmi \xe8 un archivio completo di algoritmi e strutture dati popolari implementati in JavaScript, organizzati per argomento e paradigma. \xc8 adatto per scopi di apprendimento e ricerca e per l'uso in produzione. Gli utenti possono trovare esempi di diversi algoritmi e strutture di dati popolari, tra cui algoritmi di crittografia, evolutivi e di apprendimento automatico. Il repository contiene spiegazioni, notazione Big O e link a ulteriori letture. Include anche un'area di gioco in cui i lettori possono sperimentare con il codice. Sono inclusi algoritmi avanzati come branch and bound e programmazione dinamica. Si noti che le donazioni sono benvenute e che \xe8 richiesta la versione 16 o superiore di Node."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35479378",children:"Discussion Service"}),".\n\"Hacker News commenta il popolare repository GitHub 'JavaScript-algorithms'. Gli utenti discutono dell'idoneit\xe0 del linguaggio per l'insegnamento e l'uso pratico, alcuni mettono in guardia da comportamenti inaspettati. Alcuni utenti di Discussion Service criticano l'implementazione dei metodi \"addBefore()\" e \"addAfter()\" delle liste collegate, mentre altri non sono d'accordo. Gli utenti di Discussion Service raccomandano ulteriori risorse, criticano l'efficienza delle strutture dati e sottolineano il valore delle risorse per l'apprendimento degli algoritmi\"."]}),"\n",(0,n.jsx)(e.h2,{id:"spacex-si-avvicina-al-primo-lancio-della-starship-super-heavy",children:"SpaceX si avvicina al primo lancio della Starship Super Heavy"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://spacenews.com/spacex-closing-in-on-first-starship-super-heavy-launch/",children:"Originale"}),".\nSpaceX ha in programma il primo lancio del veicolo Starship in scala reale verso la fine di aprile, in attesa dell'approvazione delle autorit\xe0; la Federal Aviation Administration, nel suo documento Operations Plan Advisory, ha indicato come data di lancio il 17 aprile, con date di riserva dal 18 al 21 aprile; L'astronave \xe8 stata completamente impilata sulla piattaforma presso la struttura Starbase di Boca Chica, in Texas, e l'azienda sta pianificando una prova di lancio la prossima settimana, seguita dal primo test di volo integrato circa una settimana dopo; non \xe8 chiaro se l'astronave entrer\xe0 in orbita, quindi eseguir\xe0 immediatamente un'accensione in deorbit per scendere, o se si tratter\xe0 di un lungo volo suborbitale."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35481775",children:"Discussion Service"}),".\nSpaceX si avvicina al lancio di Starship Super Heavy, con commenti che sottolineano l'importanza del progetto per i viaggi spaziali commerciali e militari e un cambiamento di mentalit\xe0. I contratti governativi costituiscono almeno l'80% delle entrate di SpaceX. I razzi criogenici a combustibile liquido della Starship sono fattibili per le missioni di dissuasione. Il finanziamento dei lanci non dipende solo dalla NASA. Un video che confronta le dimensioni dei razzi attira l'attenzione. SpaceX punta al lancio il 20 aprile. La FAA valuta i problemi di sicurezza. Reazioni contrastanti all'atteggiamento irriverente di Musk."]}),"\n",(0,n.jsx)(e.h2,{id:"costruire-sintetizzatori-musicali-con-query-sql",children:"Costruire sintetizzatori musicali con query SQL"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/ClickHouse/NoiSQL",children:"Originale"}),".\nUn repository GitHub chiamato NoiSQL consente di generare suoni musicali con query SQL, utilizzando onde di base, oscillatori, sequencer, LFO e generatori di rumore. Creati in formato PCM stereo a 44,1 kHz e 16 bit, gli utenti possono controllare i segnali definendo funzioni ed espressioni in SQL. NoiSQL fornisce istruzioni ed esempi per imparare a usarlo. Il progetto pu\xf2 generare note e ritmi musicali con ClickHouse e pu\xf2 creare diversi formati di file. Sebbene il progetto abbia alcune limitazioni, \xe8 un modo innovativo per sperimentare le caratteristiche di ClickHouse e potrebbe potenzialmente espandersi per includere la generazione di video. Gli utenti possono contribuire al progetto con nuovi esempi."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35482636",children:"Discussion Service"}),".\nUn progetto che costruisce sintetizzatori con query SQL. I commentatori di Discussion Service apprezzano l'idea unica e citano progetti simili. Alcuni utenti notano la mancanza di spiegazioni e le potenziali vulnerabilit\xe0 all'iniezione SQL."]}),"\n",(0,n.jsx)(e.h2,{id:"la-pi\xf9-lunga-linea-retta-in-gran-bretagna-senza-attraversare-una-strada-pubblica",children:"La pi\xf9 lunga linea retta in Gran Bretagna senza attraversare una strada pubblica"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://www.statsmapsnpix.com/2023/04/the-longest-straight-line-in-great.html",children:"Originale"}),".\nIn Gran Bretagna \xe8 stata trovata una linea retta pi\xf9 lunga senza attraversare una strada pubblica rispetto a quella identificata da Ordnance Survey nel 2019. La linea retta pi\xf9 lunga tra le strade in Gran Bretagna \xe8 anche la pi\xf9 lunga di tutto il Regno Unito. Il prodotto OS Open Roads fornisce molti dati aperti, ma a volte include strade che non sono pubbliche. Le strade ad accesso locale limitato sono solitamente sentieri privati non asfaltati. La linea pi\xf9 lunga della Gran Bretagna si trova a ovest della A9 anzich\xe9 a est. Sebbene i dati della mappatura siano utili, devono essere presi con le molle."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35481380",children:"Discussion Service"}),".\nScoperta la linea retta pi\xf9 lunga della Gran Bretagna; potrebbe non essere perfettamente retta. Alcune discussioni sulla distanza dalle strade, sull'accessibilit\xe0 delle strade sterrate e sulla popolazione. Gli utenti menzionano aree remote del mondo e la possibilit\xe0 di automatizzare la ricerca. Discussione sull'accordo di Schengen e sulle statistiche dei passaporti."]}),"\n",(0,n.jsx)(e.h2,{id:"flipper-zero-bandito-da-amazon-per-essere-un-dispositivo-di-scrematura-delle-carte-di-credito",children:'Flipper Zero bandito da Amazon per essere un "dispositivo di scrematura delle carte di credito".'}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.bleepingcomputer.com/news/technology/flipper-zero-banned-by-amazon-for-being-a-card-skimming-device-/",children:"Originale"}),'.\nAmazon ha vietato la vendita di Flipper Zero sulla sua piattaforma, accusandolo di essere un "dispositivo per lo skimming delle carte". Il dispositivo \xe8 uno strumento compatto, portatile e programmabile che pu\xf2 aiutare a sperimentare e a eseguire il debug di vari dispositivi digitali e hardware. Gli utenti hanno mostrato le sue capacit\xe0, stimolando il divieto di Amazon. Alcuni link a pagine Amazon precedentemente disponibili che vendevano lo strumento Flipper Zero sono morti, mentre altri lo elencano come "non disponibile". Anche l\'agenzia nazionale brasiliana per le telecomunicazioni ha sequestrato gli acquisti di Flipper Zero in arrivo, a causa del suo presunto utilizzo da parte di criminali. \xc8 ancora possibile acquistare Flipper Zero dal negozio ufficiale del produttore.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35481580",children:"Discussion Service"}),".\nAmazon vieta l'acquisto di Flipper Zero in quanto considerato un dispositivo di scrematura delle carte di credito, ma il dispositivo pu\xf2 essere acquistato dal negozio ufficiale. Gli acquirenti lo trovano interessante ma non utile. La politica di divieto del Lockpick \xe8 incoerente e non documentata. I produttori di Flipper Zero utilizzano una societ\xe0 con sede negli Stati Uniti per i pagamenti, sollevando problemi di sicurezza. La motivazione di Amazon \xe8 stata messa in dubbio per evitare che i titoli dei giornali li associassero alla criminalit\xe0. Flipper Zero \xe8 stato vietato a causa del suo potenziale per le attivit\xe0 illegali, ma alcuni sostengono l'incoerenza con le politiche di Amazon. Alcuni vedono la possibilit\xe0 che Amazon sviluppi una propria versione taroccata. Flipper Zero \xe8 stato rimosso da Amazon ed eBay, ma pu\xf2 ancora essere acquistato attraverso il sito ufficiale."]}),"\n",(0,n.jsx)(e.h2,{id:"reverse-engineering-dellapi-di-facebook-messenger",children:"Reverse Engineering dell'API di Facebook Messenger"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://intuitiveexplanations.com/tech/messenger",children:"Originale"}),".\nL'autore ha effettuato il reverse engineering dell'API di Facebook Messenger per creare Messyger, un programma a riga di comando. Il post spiega il processo di login e i cookie e offre il codice Python su GitHub. Viene sottolineato il comportamento etico e vengono forniti suggerimenti per effettuare richieste al di fuori del browser."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35477160",children:"Discussion Service"}),".\nGli sviluppatori sostengono che le API di Messenger sono gonfie e inefficienti. La libreria delle applicazioni di Facebook ha legami JNI. Necessit\xe0 di client di terze parti, citata la legge sui mercati digitali. Preoccupazioni per lo spam e la raccolta di dati, strumenti di reverse engineering condivisi. I motivi di profitto spingono a ridurre lo spam, alcuni sostengono l'intervento del governo. La regolamentazione dovrebbe concentrarsi sui fornitori di cloud, non sui giardini recintati. Gli utenti mettono in discussione la nozione di propriet\xe0 e i salvataggi aziendali."]}),"\n",(0,n.jsx)(e.h2,{id:"le-macchine-di-tatjana-van-vark",children:"Le macchine di Tatjana van Vark"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://craftsmanshipmuseum.com/artisan/tatjana-van-vark/",children:"Originale"}),".\nTatjana van Vark, ricercatrice indipendente dei Paesi Bassi, ha costruito, replicato e restaurato un'ampia variet\xe0 di strumenti scientifici. I suoi elaborati progetti mostrano una superba maestria e attenzione ai dettagli, spesso con complessit\xe0 che vanno oltre le apparenze. Il lavoro di Tatjana l'ha portata in molte regioni di studio scientifico, costruendo pezzi di elettronica, ottica, crittologia, chimica organica e altro ancora. Nonostante le sue abilit\xe0 di macchinista autodidatta, il suo laboratorio contiene macchine di alta qualit\xe0 in grado di gestire le esigenze del suo lavoro di precisione. Il suo lavoro \xe8 artigianato scientifico ai massimi livelli, con impressionanti mostre fotografiche disponibili sul suo sito web."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35483539",children:"Discussion Service"}),".\nIl lavoro di Tatjana van Vark \xe8 incredibile e lei \xe8 un'hacker estrema, che costruisce strumenti da zero. Ha una vasta gamma di competenze e ha prodotto molti lavori che richiederebbero una vita intera per essere rivisti. Si teme che il numero di esperti si stia riducendo, dato che la tecnologia si evolve pi\xf9 velocemente di quanto si possa insegnare. Tatjana van Vark e gli artigiani come lei non sono mai stati cos\xec comuni."]}),"\n",(0,n.jsx)(e.h2,{id:"grande-palla-di-fango-1999",children:"Grande palla di fango (1999)"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://www.laputan.org/mud/",children:"Originale"}),".\nL'articolo esplora l'architettura software BIG BALL OF MUD e il motivo per cui persiste nonostante gli approcci di alto livello. Vengono discussi sette modelli, tra cui il codice usa e getta e la crescita frammentaria, e le cause che li determinano, come i vincoli di tempo e la trascuratezza dell'architettura. Un'architettura prematura pu\xf2 ostacolare l'evoluzione e l'inesperienza o il turnover dei dipendenti possono limitare la sofisticazione. La programmazione a coppie e le revisioni del codice sono consigliate per un controllo immediato, mentre il refactoring, la riparazione e il consolidamento sono fondamentali per combattere la GRANDE PALLA DI FANGO. Sottolinea l'importanza della crescita incrementale, della manutenzione, dell'adattamento e dei test rigorosi. La ricostruzione di un sistema pu\xf2 essere necessaria, ma il refactoring pu\xf2 fornire un'alternativa raccogliendo elementi architettonici dal sistema attuale."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35481309",children:"Discussion Service"}),".\nL'articolo \"Big Ball of Mud (1999)\" \xe8 un pezzo molto apprezzato sull'ingegneria del software. Diversi utenti ne lodano l'intuizione e la pertinenza, citandolo come una spiegazione esauriente di ci\xf2 che si vede ogni settimana nelle situazioni reali. Altri indicano altri articoli altrettanto significativi o sviluppi successivi nell'ingegneria del software, come i microservizi. Alcuni utenti commentano le loro esperienze personali relative all'articolo. Infine, alcuni utenti criticano la formattazione dell'articolo o notano che \xe8 stato pubblicato in precedenza."]}),"\n",(0,n.jsx)(e.h2,{id:"yann-lecun-e-andrew-ng-perch\xe9-la-pausa-di-6-mesi-sullintelligenza-artificiale-\xe8-una-cattiva-idea-video",children:"Yann LeCun e Andrew Ng: Perch\xe9 la pausa di 6 mesi sull'intelligenza artificiale \xe8 una cattiva idea [video]."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.youtube.com/watch?v=BY9KV8uCtj4",children:"Originale"}),".\nQuesto non \xe8 il contenuto effettivo dell'articolo. Si prega di fornire il testo da riassumere."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35484093",children:"Discussion Service"}),".\nYann LeCun e Andrew Ng criticano la pausa di 6 mesi dell'IA, suggerendo che non \xe8 realistica e che d\xe0 un vantaggio a OpenAI. Vengono evidenziati i dibattiti sull'inverno dell'IA, sulla rappresentazione del pensiero umano e sulla disgregazione della societ\xe0. Il progresso dell'IA offre capacit\xe0 inaspettate al di l\xe0 del testo e suscita preoccupazioni per la perdita di posti di lavoro e la povert\xe0. Gli esperti hanno opinioni contrastanti sull'efficacia della pausa sullo sviluppo dell'IA e sui rischi di un'IA non regolamentata. Vengono sollevate la potenziale minaccia di un'intelligenza artificiale superiore a quella umana e le tecnologie di sorveglianza dell'apprendimento profondo, oltre alle preoccupazioni sull'allineamento dell'IA con gli obiettivi umani."]}),"\n",(0,n.jsx)(e.h2,{id:"lnsa-ha-creato-un-corso-online-di-cybersicurezza-con-100-classi",children:"L'NSA ha creato un corso online di cybersicurezza con 100 classi"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://clark.center/c/nccp",children:"Originale"}),".\nL'NSA ha creato un corso online sulla sicurezza informatica con centinaia di lezioni disponibili. Il corso, chiamato CLARK, copre un'ampia gamma di argomenti, tra cui la sicurezza delle reti, la crittografia e le minacce informatiche. Le lezioni sono pensate sia per i principianti che per gli esperti e sono accessibili gratuitamente a chiunque abbia una connessione a Internet. Il corso \xe8 stato oggetto di controversie: alcuni critici hanno affermato che fornisce una backdoor all'NSA per accedere a informazioni private. Tuttavia, la NSA ha negato queste affermazioni e ha dichiarato che il corso \xe8 puramente educativo."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35481456",children:"Discussion Service"}),".\nL'NSA ha creato un corso di cybersecurity, ma ci sono preoccupazioni riguardo all'uso degli exploit 0day da parte dell'agenzia nelle operazioni offensive. Alcuni utenti notano che la divisione tra offesa e difesa \xe8 meno minacciosa di quanto sembri. Il corso fa parte del sistema CLARK, parzialmente finanziato dalla NSA, ma gestito principalmente dalla Towson University. Alcuni utenti criticano la mancanza di copertura di alcuni argomenti nel corso."]}),"\n",(0,n.jsx)(e.h2,{id:"sostituzione-di-cattivi-sistemi-con-cattivi-sistemi",children:"Sostituzione di cattivi sistemi con cattivi sistemi"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://seths.blog/2023/04/replacing-bad-systems-with-bad-systems/",children:"Originale"}),".\nNel suo post sul blog, Seth utilizza la metafora dei parchimetri obsoleti per illustrare la necessit\xe0 di ripensare e migliorare i sistemi difettosi. Anche se la loro sostituzione pu\xf2 sembrare costosa, i sistemi centralizzati come l'app Parkmobile hanno spesso i loro difetti. Tornando all'obiettivo originario di generare entrate e impedire il parcheggio per tutto il giorno, Seth suggerisce di implementare un'applicazione gratuita che scansiona un codice per consentire un periodo di sosta. Altre opzioni per incrementare le entrate sono un servizio di pagamento online o la vendita di pass per il parcheggio con diverse opzioni di sconto. Sebbene sia difficile fare scelte UX per un sistema pubblico, i sistemi distribuiti come WordPress hanno prosperato grazie al loro design decentralizzato e facile da usare. Il vantaggio principale dei sistemi distribuiti \xe8 la loro capacit\xe0 di migliorare nel tempo, piuttosto che calcificarsi come i sistemi centralizzati. Per andare avanti, Seth suggerisce di dare priorit\xe0 a soluzioni migliori invece che a pi\xf9 soluzioni."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35476350",children:"Discussion Service"}),".\nUn sistema di parcheggio pi\xf9 semplice in Danimarca prevede un orologio manuale, con multe per gli imbroglioni. Gli utenti segnalano sistemi simili all'estero. Spesso si ricorre a soluzioni complesse nonostante le opzioni semplici. I parchimetri di Chicago hanno generato 200 milioni di dollari in 10 anni. I nuovi parchimetri elettronici sono meno convenienti dei classici. I governi hanno difficolt\xe0 con i sistemi di pagamento e a volte li lasciano ai venditori. I parchimetri sono usati principalmente per il denaro, ma impediscono anche di parcheggiare per tutto il giorno. Secondo un commentatore, l'articolo non ha senso, mentre un altro critica l'autore."]}),"\n",(0,n.jsx)(e.h2,{id:"neovim-09",children:"Neovim 0.9"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/neovim/neovim/commit/040f1459849ab05b04f6bb1e77b3def16b4c2f2b",children:"Originale"}),'.\n\xc8 stata rilasciata la versione 0.9.0 di Neovim, con modifiche a iconv, libintl, params opzionali, lua2dox, tokens semantici, \'+tui\', supporto ai moduli dei nodi Yarn ed evidenziazione dei blocchi di codice. \xc8 stata rilasciata anche la versione 8.2.2902 di Vim, con la correzione di bug e il miglioramento dello scripting Lua e del supporto LSP. L\'ultima versione di Neovim presenta nuove interessanti caratteristiche e miglioramenti della stabilit\xe0, mentre Vim si concentra sulla correzione di bug e sul miglioramento delle funzionalit\xe0. Gli aggiornamenti di Neovim includono miglioramenti a "treesitter", "tui" e "windows", dalla correzione di software al miglioramento della documentazione, semplificando l\'esperienza di Neovim e consolidando la sua posizione di programma capace e facile da usare. Altri aggiornamenti includono modifiche alla funzione "expect_unchanged()", EditorConfig e l\'evidenziazione della sintassi per i file di aiuto, un\'istanza headless, migliori capacit\xe0 del client LSP e il supporto di plugin per le GUI.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35480629",children:"Discussion Service"}),".\nNeovim 0.9.0 rende obsoleto 'exrc' e aggiunge un \"database di fiducia\". Gli esperti raccomandano appImage o .local per l'installazione. Il supporto per EditorConfig \xe8 ora integrato. Dibattito sui meriti di Neovim, mentre alcuni criticano la frammentazione, altri suggeriscono i gestori di plugin. Neovim consente nuovi strumenti e plugin. Lua presenta vantaggi per lo sviluppo di plugin. Helix Editor ha un modello a oggetti, un server di linguaggio a configurazione zero e un tutor. La sua selezione \xe8 meno flessibile, ma gli utenti ne apprezzano l'usabilit\xe0 e l'efficienza."]}),"\n",(0,n.jsx)(e.h2,{id:"qual-\xe8-la-vostra-migliore-risorsa-per-tenervi-aggiornati-sugli-sviluppi-dellintelligenza-artificiale",children:"Qual \xe8 la vostra migliore risorsa per tenervi aggiornati sugli sviluppi dell'intelligenza artificiale?"}),"\n",(0,n.jsx)(e.p,{children:"N/A (Poich\xe9 si tratta solo di istruzioni generali per il riassunto, non c'\xe8 testo da riassumere)."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35479853",children:"Discussion Service"}),".\nGli utenti di Discussion Service consigliano risorse per tenersi aggiornati sugli sviluppi dell'IA, tra cui il sito web Papers with Code, blog e newsletter. Si consiglia cautela a causa del sovraccarico di informazioni. Alcuni offrono risorse per i principianti. I recenti progressi nell'IA, comprese le innovazioni hardware e algoritmiche, hanno migliorato l'addestramento delle reti neurali di grandi dimensioni, raggiungendo prestazioni di livello umano. Il dibattito continua sulle scoperte rivoluzionarie."]}),"\n",(0,n.jsx)(e.h2,{id:"prova-diretta-delluso-di-pi\xf9-droghe-nellet\xe0-del-bronzo-dal-test-sui-capelli-umani",children:"Prova diretta dell'uso di pi\xf9 droghe nell'Et\xe0 del Bronzo dal test sui capelli umani"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.nature.com/articles/s41598-023-31064-2",children:"Original"}),".\nUno studio ha trovato prove dirette dell'uso di pi\xf9 specie di piante psicoattive nell'Et\xe0 del Bronzo a Minorca, utilizzando l'analisi di capelli umani. I capelli contenevano efedrina, atropina e scopolamina. Gli archeologi normalmente deducono l'uso di sostanze che alterano la mente dai manufatti, ma questa analisi \xe8 diretta. Questa scoperta getta nuova luce sull'uso di droghe nelle societ\xe0 antiche, indicando conoscenze specialistiche e un potenziale uso sciamanico. Lo studio rivela l'importanza di comprendere il ruolo delle piante psicoattive e dell'uso di droghe nelle culture del passato. Numerosi studi mostrano prove dell'uso di piante psicoattive nelle culture antiche, evidenziando la lunga storia dell'uso di droghe da parte dell'uomo."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35486923",children:"Discussion Service"}),".\nI test sui capelli rivelano la presenza di droghe nell'Et\xe0 del Bronzo con pi\xf9 specie psicoattive. I commenti discutono l'impatto sociale dell'uso di droghe, le scelte personali, l'educazione e i valori. Le proibizioni delle droghe hanno radici nella salute pubblica, nella moralit\xe0 e nel razzismo. Articolo neutro che evita pregiudizi e speculazioni politiche."]}),"\n",(0,n.jsx)(e.h2,{id:"agenti-della-polizia-di-new-york-si-vantano-di-fare-gli-straordinari-in-una-registrazione-accidentale",children:"Agenti della polizia di New York si vantano di fare gli straordinari in una registrazione accidentale"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording",children:"Originale"}),'.\nUna registrazione accidentale effettuata durante l\'arresto di un operaio edile ha rivelato che gli agenti di polizia si vantano di "mungere gli straordinari" e usano un linguaggio sprezzante nei confronti dei detenuti. La registrazione fa luce su come le recenti riforme della giustizia penale abbiano influenzato il modo in cui gli agenti processano gli arresti e riscuotono gli straordinari. Si ipotizza che gli agenti di polizia stiano approfittando delle modifiche apportate alle leggi sulla cauzione e sulla scoperta per accumulare ulteriori straordinari. La Polizia di New York ha rifiutato di commentare la registrazione, che include anche commenti insensibili fatti dagli agenti sui detenuti.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35487036",children:"Discussion Service"}),".\nGli agenti della polizia di New York si vantano di fare gli straordinari, ma l'articolo rivela l'uso di insulti, battute sull'istituzionalizzazione delle persone, ecc. Alcuni ritengono che le forze dell'ordine negli Stati Uniti abbiano problemi ben peggiori e che gli straordinari della polizia siano un depistaggio. Altri sostengono che il fatto di sfruttare gli straordinari prolungando la detenzione sia anticostituzionale e meriti un'accusa di reato. La corruzione delle forze di polizia ha portato a chiedere la loro abolizione e sostituzione. La mancanza di un'adeguata supervisione e di controlli permette di sfruttare gli straordinari e di commettere illeciti. Ci sono preoccupazioni riguardo al comportamento delle persone che ricevono armi e un trattamento preferenziale secondo la legge."]}),"\n",(0,n.jsx)(e.h2,{id:"mostra-chatgdb---assistente-gdb-alimentato-da-gpt",children:"Mostra ChatGDB - Assistente GDB alimentato da GPT"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/pgosar/ChatGDB",children:"Originale"}),".\nChatGDB \xe8 uno strumento che migliora l'esperienza di debug in GDB utilizzando la potenza di ChatGPT, consentendo l'esecuzione automatica di comandi in linguaggio naturale. Gli utenti possono anche chiedere a ChatGPT di spiegare il comando appena eseguito o di porre una domanda. Per l'installazione \xe8 necessario installare Python versione 3.3 o superiore e pip, seguito dal comando ",(0,n.jsx)(e.code,{children:"pip3 install chatgdb"})," e dalla creazione di un eseguibile con ",(0,n.jsx)(e.code,{children:"chatgdb -k <API KEY>"}),". Lo strumento pu\xf2 essere utilizzato all'interno di GDB digitando ",(0,n.jsx)(e.code,{children:"chat"})," seguito dal comando desiderato, mentre il comando ",(0,n.jsx)(e.code,{children:"explain"})," pu\xf2 essere utilizzato per richiedere una spiegazione del comando precedente o per porre una domanda."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35483933",children:"Discussion Service"}),".\nChatGDB \xe8 un assistente GDB alimentato da GPT, che migliora i flussi di lavoro di debug. L'utente di Discussion Service nota il codice minimo del programma. ChatGPT accelera la comprensione dell'utente per le attivit\xe0 di refactoring e le tecnologie non familiari. Viene suggerita una versione CLI di ChatGPT. ChatGPT accelera i flussi di lavoro, nonostante alcuni utenti preferiscano la memoria muscolare. ChatGPT-3 presenta un prompt in linguaggio naturale per GDB, utile per \"perdite di memoria e difetti di segmentazione\". L'interfaccia \xe8 ancora poco maneggevole in alcuni scenari, mentre il font e lo schema dei colori sono ben accolti."]})]})}function u(i={}){const{wrapper:e}={...(0,t.R)(),...i.components};return e?(0,n.jsx)(e,{...i,children:(0,n.jsx)(d,{...i})}):d(i)}}}]);